import{_ as e,o as a,a as s,a2 as o}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"llms.txt","description":"","frontmatter":{},"headers":[],"relativePath":"ai/llms-txt.md","filePath":"ai/llms-txt.md","lastUpdated":1789464754000}'),l={name:"ai/llms-txt.md"};function i(r,t,n,d,h,c){return a(),s("div",null,t[0]||(t[0]=[o(`<h1 id="llms-txt" tabindex="-1">llms.txt <a class="header-anchor" href="#llms-txt" aria-label="Permalink to &quot;llms.txt&quot;">​</a></h1><p>This site publishes its documentation as two plain-text files for AI tools, following the <a href="https://llmstxt.org" target="_blank" rel="noreferrer">llms.txt</a> convention:</p><table tabindex="0"><thead><tr><th>File</th><th>Contains</th><th>Use it when</th></tr></thead><tbody><tr><td><a href="https://devdocs.bagisto.com/llms.txt" target="_blank" rel="noreferrer"><code>llms.txt</code></a></td><td>The site&#39;s title and summary, then a table of contents that links every page, grouped by section</td><td>The tool can follow links, or you want it to find the right page first</td></tr><tr><td><a href="https://devdocs.bagisto.com/llms-full.txt" target="_blank" rel="noreferrer"><code>llms-full.txt</code></a></td><td>The full text of every page, one after another</td><td>The tool can&#39;t browse, or you are building a search index of the documentation</td></tr></tbody></table><p>Both files describe the same Bagisto release as the site. The links in <code>llms.txt</code> are site-relative, such as <code>/getting-started/installation</code>, so resolve them against <code>https://devdocs.bagisto.com</code>.</p><h2 id="using-them" tabindex="-1">Using Them <a class="header-anchor" href="#using-them" aria-label="Permalink to &quot;Using Them&quot;">​</a></h2><ul><li><strong>A tool that reads URLs</strong>: give it <code>https://devdocs.bagisto.com/llms.txt</code> and ask it to open the pages it needs.</li><li><strong>A chat that can&#39;t browse</strong>: download a file and attach it. <code>llms-full.txt</code> holds the whole site, several hundred kilobytes of text, which can be more than a model&#39;s context window takes. Attach <code>llms.txt</code> and paste in the pages you need instead.</li><li><strong>A coding agent in your project</strong>: add a line pointing to <code>https://devdocs.bagisto.com/llms.txt</code> to the project&#39;s <code>AGENTS.md</code> or <code>CLAUDE.md</code>. Pair it with the <a href="./agent-skills.html">Agent Skills</a>, which carry the rules an agent follows while it writes code.</li><li><strong>Your own search index</strong>: split <code>llms-full.txt</code> at each page&#39;s top-level heading and index the parts.</li></ul><p>To keep local copies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://devdocs.bagisto.com/llms.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://devdocs.bagisto.com/llms-full.txt</span></span></code></pre></div><p>Download them again after a Bagisto release, because the files change with the site.</p><h2 id="the-api-reference-has-its-own" tabindex="-1">The API Reference Has Its Own <a class="header-anchor" href="#the-api-reference-has-its-own" aria-label="Permalink to &quot;The API Reference Has Its Own&quot;">​</a></h2><p>The REST and GraphQL reference publishes the same pair for the <code>bagisto/bagisto-api</code> package. <a href="https://api-docs.bagisto.com/llms.txt" target="_blank" rel="noreferrer"><code>api-docs.bagisto.com/llms.txt</code></a> lists every Shop and Admin endpoint, and <a href="https://api-docs.bagisto.com/llms-full.txt" target="_blank" rel="noreferrer"><code>api-docs.bagisto.com/llms-full.txt</code></a> holds every page. An optional MCP server, <a href="https://github.com/bagisto/mcp" target="_blank" rel="noreferrer"><code>bagisto/mcp</code></a>, lets an agent search that reference from the editor; see <a href="https://api-docs.bagisto.com/api/build-with-ai/" target="_blank" rel="noreferrer">Build with AI</a>.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./agent-skills.html">Agent Skills</a>: the conventions a coding agent follows while it writes Bagisto code.</li><li><a href="./introduction.html">AI in Bagisto</a>: the generative and agentic features, and where to start.</li></ul>`,13)]))}const m=e(l,[["render",i]]);export{g as __pageData,m as default};
